 - ESERCIZIO 1 (Livello Base - Filtri su Stringhe e Valori Numerici): SELECT titolo_libro, autore_libro, prezzo_unitario FROM registro_vendite WHERE categoria_libro = "Informatica" AND prezzo_unitario > 30.00 AND prezzo_unitario < 50.00;
 - ESERCIZIO 2 (Livello Intermedio - Funzioni di Stringa e Ordinamento): SELECT DISTINCT UPPER(CONCAT(nome_cliente, " ", cognome_cliente)) AS cliente_completo, email_cliente, citta_cliente FROM registro_vendite ORDER BY citta_cliente DESC;
 - ESERCIZIO 3 (Livello Intermedio - Aggregazione semplice e GROUP BY): SELECT stato_ordine, COUNT(stato_ordine) AS totale_ordini, SUM(quantita_ordinata) AS copie_totali FROM registro_vendite GROUP BY stato_ordine;
 - ESERCIZIO 4 (Livello Avanzato - WHERE vs HAVING con Aggregazioni): SELECT citta_cliente, SUM(prezzo_unitario * quantita_ordinata) AS spesa_totale FROM registro_vendite WHERE stato_ordine = "Completato" GROUP BY citta_cliente HAVING SUM(prezzo_unitario * quantita_ordinata) > 150.00;
 - ESERCIZIO 5 (Livello Avanzato - Conteggi Distinti e Filtro sui Gruppi): SELECT autore_libro, COUNT(DISTINCT id_ordine) AS numero_clienti_distinti FROM registro_vendite WHERE MONTH(data_ordine) = "03" AND YEAR(data_ordine) = "2025" GROUP BY autore_libro HAVING COUNT(DISTINCT id_ordine) >= 2;